// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {

        bool ok;
        try c.assertionDisputedCallback(assertionId) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.assume(ok == true);

        address arbitrary = address(uint160(uint256(assertionId)));
        vm.assume(arbitrary != address(this));

        vm.deal(arbitrary, 1 ether);
        bytes32 identifier = keccak256(abi.encodePacked(assertionId, "id"));
        uint256 time = uint256(assertionId);
        bytes memory ancillary = abi.encodePacked(assertionId);

        bool succeeded;
        vm.prank(arbitrary);
        try c.requestPrice(identifier, time, ancillary) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        assertTrue(succeeded == false);
    }
}
